// === Tab: mySketch ===
function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  stroke(255);
  strokeWeight(3);
}

function draw() {
  background(0);
  translate(width/2, height/2);

  let r1=0;
  let r2=0;
  let t1=map(cos(radians(frameCount)),-1,1,0.03,0.2);
  let t2=1;
  while (r1<360) {
    let a=sin(r2)*height/2;
    point(cos(r1)*a, sin(r1)*a);
    r1+=t1;
    r2+=t2;
  }
}

